// Flowable schema access. The data lives in schema/flowable-<version>.json (generated by
// scripts/extract-flowable-schema.mjs); nothing about Flowable is hard-coded here.
import flowable720 from '../../schema/flowable-7.2.0.json' with { type: 'json' };

const schemas = new Map();
let activeVersion = null;

// Register a schema document (a version).
function registerSchema(doc) {
  schemas.set(doc.version, doc);
  activeVersion ??= doc.version;
}

// Layer extra definitions on top of the active schema, e.g. {elements: {boundaryEvent: {attributes: [...]}}}.
export function extendSchema(patch, version = activeVersion) {
  const base = schemas.get(version);
  for (const [name, el] of Object.entries(patch.elements || {})) {
    const cur = (base.elements[name] ??= { attributes: [], children: [] });
    cur.attributes.push(...(el.attributes || []));
    cur.children.push(...(el.children || []));
  }
  Object.assign(base.attributeTypes, patch.attributeTypes || {});
}

export const getSchema = () => schemas.get(activeVersion);
export const localName = (qname) => qname.slice(qname.indexOf(':') + 1);

export const elementSchema = (qname) => getSchema().elements[localName(qname)] ?? null;

// Resolve a prefixed attribute name to {ns, name} given the schema's namespace prefixes.
export function attributeKey(attr) {
  const i = attr.name.indexOf(':');
  return i < 0 ? { ns: 'bpmn', name: attr.name } : { ns: attr.name.slice(0, i), name: attr.name.slice(i + 1) };
}

export function attributeSpec(elementQName, ns, name) {
  const el = elementSchema(elementQName);
  return el?.attributes.find((a) => a.ns === ns && a.name === name) ?? null;
}

export const childSpec = (elementQName, name) => elementSchema(elementQName)?.children.find((c) => c.name === name) ?? null;

registerSchema(flowable720);
